/// The resources `paths` include for `entities`, path by path and each in
/// linkage order: each once, and none of `entities` among them. `paths` are
/// those `include_paths` admitted, so no other path occurs.
async fn ontogen_section_included(
    state: &AppState,
    entities: &[Section],
    paths: &[&str],
) -> Result<Vec<OntogenAnyResource>, OntogenErrorObject> {
    let mut included = OntogenIncluded::new("sections", entities.iter().map(|entity| entity.id.as_str()));
    for path in paths {
        match *path {
            "parent" => {
                let ids = included.new_ids("sections", entities.iter().map(|entity| entity.parent_id.as_str()));
                let collection = "/api/sections";
                for related in ontogen_section_fetch(state, &ids).await? {
                    included.push(ontogen_section_as_resource(&related, collection))?;
                }
            }
            "children" => {
                let ids = included
                    .new_ids("sections", entities.iter().flat_map(|entity| entity.children.iter().map(String::as_str)));
                let collection = "/api/sections";
                for related in ontogen_section_fetch(state, &ids).await? {
                    included.push(ontogen_section_as_resource(&related, collection))?;
                }
            }
            _ => {}
        }
    }
    Ok(included.finish())
}

/// The resources `paths` include for `entities`, path by path and each in
/// linkage order: each once, and none of `entities` among them. `paths` are
/// those `include_paths` admitted, so no other path occurs.
async fn ontogen_task_included(
    state: &AppState,
    entities: &[Task],
    paths: &[&str],
) -> Result<Vec<OntogenAnyResource>, OntogenErrorObject> {
    let mut included = OntogenIncluded::new("tasks", entities.iter().map(|entity| entity.id.as_str()));
    for path in paths {
        match *path {
            "parent" => {
                let ids = included.new_ids("tasks", entities.iter().filter_map(|entity| entity.parent_id.as_deref()));
                let collection = "/api/tasks";
                for related in ontogen_task_fetch(state, &ids).await? {
                    included.push(ontogen_task_as_resource(&related, collection))?;
                }
            }
            "subtasks" => {
                let ids = included
                    .new_ids("tasks", entities.iter().flat_map(|entity| entity.subtasks.iter().map(String::as_str)));
                let collection = "/api/tasks";
                for related in ontogen_task_fetch(state, &ids).await? {
                    included.push(ontogen_task_as_resource(&related, collection))?;
                }
            }
            "tags" => {
                let ids =
                    included.new_ids("tags", entities.iter().flat_map(|entity| entity.tags.iter().map(String::as_str)));
                let collection = "/api/tags";
                for related in ontogen_tag_fetch(state, &ids).await? {
                    included.push(ontogen_tag_as_resource(&related, collection))?;
                }
            }
            _ => {}
        }
    }
    Ok(included.finish())
}

