// ── Note Handlers ──

async fn note_list(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: OntogenQuery<OntogenPagedListParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let order = query.sort_order("notes")?;
    let include = query.include_paths("notes", &[], &["tags"])?;
    let (offset, limit) = ontogen_page(&query, 2, 3)?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let items = note::list(&ontogen_store, &order, Some(u64::from(limit)), Some(u64::from(offset)))
        .await
        .map_err(ontogen_app_error)?;
    let total = note::count(&ontogen_store).await.map_err(ontogen_app_error)?;
    let collection = "/api/notes";
    let data: Vec<_> = items.iter().map(|entity| ontogen_note_as_resource(entity, collection)).collect();
    let links = ::ontogen_jsonapi::links::pagination_links(collection, &link_query, offset, limit, total);
    let mut document = OntogenDocument::new(data, links).with_meta(OntogenPageMeta { total, limit, offset });
    if include.is_some() {
        document = document.with_included(Vec::new());
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

async fn note_get_by_id(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath(id): OntogenPath<OntogenLookupKey>,
    query: OntogenQuery<OntogenGetParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let include = query.include_paths("notes", &[], &["tags"])?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let entity = note::get_by_id(&ontogen_store, ontogen_note_lookup_key(&id)?).await.map_err(ontogen_app_error)?;
    let collection = "/api/notes";
    let mut document = OntogenDocument::resource(ontogen_note_as_resource(&entity, collection), &link_query);
    if include.is_some() {
        document = document.with_included(Vec::new());
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

async fn note_create(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: Result<OntogenQuery<OntogenNoParams>, OntogenErrorObject>,
    body: OntogenBody,
) -> Result<OntogenResponse, OntogenErrorObject> {
    query?;
    let body = body.into_bytes()?;
    let collection = "/api/notes";
    let endpoint = OntogenEndpoint { type_name: "notes", path: collection };
    let data = ::ontogen_jsonapi::request::parse_create(&body, endpoint, |id| {
        ::ontogen_core::id::validate_id(id).map_err(|e| e.reason)
    })?;
    let fields = ontogen_note_request_fields(&data, true)?;
    let input: CreateNoteInput = ontogen_from_fields(fields)?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let entity = note::create(&ontogen_store, input).await.map_err(|e| match e {
        e @ crate::schema::AppError::NoteAlreadyExists(..) if data.id.is_some() => {
            ontogen_app_error(e).with_pointer("/data/id")
        }
        e => ontogen_app_error(e),
    })?;
    let document =
        OntogenDocument::resource(ontogen_note_as_resource(&entity, collection), &OntogenCanonicalQuery::new());
    let location = document.data().and_then(OntogenResourceObject::links).map(OntogenLinks::self_link);
    Ok(::ontogen_jsonapi::response::created(location, &document))
}

