                note::list_tags(&ontogen_state, &ontogen_entity.id).await.map_err(ontogen_app_error)?;
            let ontogen_total = ontogen_members.len() as u64;
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_members
                    .iter()
                    .skip(ontogen_offset as usize)
                    .take(ontogen_limit as usize)
                    .map(|ontogen_member| OntogenResourceIdentifier::new("tags", ontogen_member.as_str()))
                    .collect(),
            );
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
