async fn section_get_by_id(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath(id): OntogenPath<OntogenLookupKey>,
    query: OntogenQuery<OntogenGetParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let include = query.include_paths("sections", &["parent", "children"], &[])?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let entity =
        section::get_by_id(&ontogen_store, ontogen_section_lookup_key(&id)?).await.map_err(ontogen_app_error)?;
    let collection = "/api/sections";
    let mut document = OntogenDocument::resource(ontogen_section_as_resource(&entity, collection), &link_query);
    if let Some(paths) = &include {
        document = document
            .with_included(ontogen_section_included(&ontogen_state, ::std::slice::from_ref(&entity), paths).await?);
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

async fn section_create(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: Result<OntogenQuery<OntogenNoParams>, OntogenErrorObject>,
    body: OntogenBody,
) -> Result<OntogenResponse, OntogenErrorObject> {
    query?;
    let body = body.into_bytes()?;
    let collection = "/api/sections";
    let endpoint = OntogenEndpoint { type_name: "sections", path: collection };
    let data = ::ontogen_jsonapi::request::parse_create(&body, endpoint, |id| {
        ::ontogen_core::id::validate_id(id).map_err(|e| e.reason)
    })?;
    let (fields, linked) = ontogen_section_request_fields(&data, true)?;
    let input: CreateSectionInput = ontogen_from_fields(fields)?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    ontogen_section_check_linked(&ontogen_state, &linked).await?;
    let entity = section::create(&ontogen_store, input).await.map_err(|e| match e {
        e @ crate::schema::AppError::SectionAlreadyExists(..) if data.id.is_some() => {
            ontogen_app_error(e).with_pointer("/data/id")
        }
        e => ontogen_app_error(e),
    })?;
    let document =
        OntogenDocument::resource(ontogen_section_as_resource(&entity, collection), &OntogenCanonicalQuery::new());
    let location = document.data().and_then(OntogenResourceObject::links).map(OntogenLinks::self_link);
    Ok(::ontogen_jsonapi::response::created(location, &document))
}

