struct OntogenSectionListFilterParams;

impl OntogenRouteQuery for OntogenSectionListFilterParams {
    const SPEC: OntogenQuerySpec = OntogenQuerySpec {
        filter: &["parent_id"],
        filter_fields: Some(::ontogen_jsonapi::filter_fields::<ListSectionsQuery>),
        sort: true,
        include: true,
        page: true,
        ..OntogenQuerySpec::NONE
    };
}

async fn section_list(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: OntogenQuery<OntogenSectionListFilterParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_filter: ListSectionsQuery = query.filter()?;
    let ontogen_filter_parent_id = query.required_filter_member::<String>("parent_id")?;
    let order = query.sort_order("sections")?;
    let include = query.include_paths("sections", &["parent", "children"], &[])?;
    let (offset, limit) = ontogen_page(&query, 2, 3)?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let items = section::list(
        &ontogen_store,
        ontogen_filter.clone(),
        &ontogen_filter_parent_id,
        &order,
        Some(u64::from(limit)),
        Some(u64::from(offset)),
    )
    .await
    .map_err(ontogen_app_error)?;
    let total =
        section::count(&ontogen_store, ontogen_filter, &ontogen_filter_parent_id).await.map_err(ontogen_app_error)?;
    let collection = "/api/sections";
    let data: Vec<_> = items.iter().map(|entity| ontogen_section_as_resource(entity, collection)).collect();
    let links = ::ontogen_jsonapi::links::pagination_links(collection, &link_query, offset, limit, total);
    let mut document = OntogenDocument::new(data, links).with_meta(OntogenPageMeta { total, limit, offset });
    if let Some(paths) = &include {
        document = document.with_included(ontogen_section_included(&ontogen_state, &items, paths).await?);
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

async fn ontogen_section_relationship_get(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath((id, rel)): OntogenPath<(OntogenLookupKey, OntogenLookupKey)>,
    OntogenRawQuery(ontogen_raw_query): OntogenRawQuery,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_collection = "/api/sections";
    match rel.as_str() {
        Some("parent") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_section_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/parent"))
                .with_related(format!("{ontogen_base}/parent"));
            let ontogen_data = OntogenLinkage::ToOne(Some(OntogenResourceIdentifier::new(
                "sections",
                ontogen_entity.parent_id.as_str(),
            )));
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("children") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_section_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/children"))
                .with_related(format!("{ontogen_base}/children"));
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_entity
                    .children
                    .iter()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("sections", ontogen_member.as_str()))
                    .collect(),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("sections", &rel)),
    }
}

async fn ontogen_section_relationship_patch(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    ontogen_path: Result<OntogenPath<(OntogenLookupKey, OntogenLookupKey)>, OntogenErrorObject>,
    ontogen_query: Result<OntogenQuery<OntogenNoParams>, OntogenErrorObject>,
    ontogen_body: OntogenBody,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let OntogenPath((id, rel)) = ontogen_path?;
    match rel.as_str() {
        Some("parent") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_one(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "sections",
                false,
            )?
            .map(|ontogen_member| OntogenLinkedId { id: ontogen_member, pointer: "/data".to_owned() });
            let ontogen_entity = ontogen_section_read(&ontogen_state, &id).await?;
            ontogen_section_check_ids(&ontogen_state, ontogen_linked.as_slice()).await?;
            ontogen_section_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "parent_id",
                ontogen_linked.map(|ontogen_member| ontogen_member.id).into(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        Some("children") => {
            ontogen_query?;
            let ontogen_bytes = ontogen_body.into_bytes()?;
            let ontogen_linked = ::ontogen_jsonapi::request::to_many_linked(
                &::ontogen_jsonapi::request::parse_relationship(&ontogen_bytes)?,
                "",
                "sections",
                None,
            )?;
            ::ontogen_jsonapi::request::refuse_cycle(&ontogen_linked, id.as_str(), "sections", "children")?;
            let ontogen_entity = ontogen_section_read(&ontogen_state, &id).await?;
            ontogen_section_check_ids(&ontogen_state, &ontogen_linked).await?;
            ontogen_section_write_field(
                &ontogen_state,
                &ontogen_entity.id,
                "children",
                ontogen_linked.into_iter().map(|ontogen_member| ontogen_member.id).collect(),
            )
            .await?;
            Ok(::ontogen_jsonapi::response::no_content())
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("sections", &rel)),
    }
}

