impl OntogenRouteQuery for OntogenTagListFilterParams {
    const SPEC: OntogenQuerySpec = OntogenQuerySpec {
        filter: &["min_title_len", "title_prefix"],
        sort: true,
        include: true,
        page: true,
        ..OntogenQuerySpec::NONE
    };
}

async fn tag_list(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: OntogenQuery<OntogenTagListFilterParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_filter_min_title_len = query.filter_member::<u32>("min_title_len")?;
    let ontogen_filter_title_prefix = query.filter_member::<String>("title_prefix")?;
    ontogen_refuse_sort(&query, "tags")?;
    let include = query.include_paths("tags", &[], &[])?;
    let (offset, limit) = ontogen_page(&query, 2, 3)?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let items = tag::list(
        &ontogen_store,
        ontogen_filter_title_prefix.as_deref(),
        ontogen_filter_min_title_len,
        Some(u64::from(limit)),
        Some(u64::from(offset)),
    )
    .await
    .map_err(ontogen_app_error)?;
    let total = tag::count(&ontogen_store, ontogen_filter_title_prefix.as_deref(), ontogen_filter_min_title_len)
        .await
        .map_err(ontogen_app_error)?;
    let collection = "/api/tags";
    let data: Vec<_> = items.iter().map(|entity| ontogen_tag_as_resource(entity, collection)).collect();
    let links = ::ontogen_jsonapi::links::pagination_links(collection, &link_query, offset, limit, total);
    let mut document = OntogenDocument::new(data, links).with_meta(OntogenPageMeta { total, limit, offset });
    if include.is_some() {
        document = document.with_included(Vec::new());
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

