async fn ontogen_task_relationship_get(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath((id, rel)): OntogenPath<(OntogenLookupKey, OntogenLookupKey)>,
    OntogenRawQuery(ontogen_raw_query): OntogenRawQuery,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_collection = "/api/tasks";
    match rel.as_str() {
        Some("parent") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/parent"))
                .with_related(format!("{ontogen_base}/parent"));
            let ontogen_data = OntogenLinkage::ToOne(
                ontogen_entity
                    .parent_id
                    .as_ref()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("tasks", ontogen_member.as_str())),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("subtasks") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/subtasks"))
                .with_related(format!("{ontogen_base}/subtasks"));
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_entity
                    .subtasks
                    .iter()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("tasks", ontogen_member.as_str()))
                    .collect(),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("tags") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_links = OntogenLinks::new(format!("{ontogen_base}/relationships/tags"))
                .with_related(format!("{ontogen_base}/tags"));
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_entity
                    .tags
                    .iter()
                    .map(|ontogen_member| OntogenResourceIdentifier::new("tags", ontogen_member.as_str()))
                    .collect(),
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, ontogen_links)))
        }
        Some("labels") => {
            let ontogen_query = OntogenQueryParams::parse(
                ontogen_raw_query.as_deref(),
                &OntogenQuerySpec { page: true, ..OntogenQuerySpec::NONE },
            )?;
            let (ontogen_offset, ontogen_limit) = ontogen_page(&ontogen_query, 2, 3)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
            let ontogen_members =
                task::list_labels(&ontogen_store, &ontogen_entity.id).await.map_err(ontogen_app_error)?;
            let ontogen_total = ontogen_members.len() as u64;
            let ontogen_data = OntogenLinkage::ToMany(
                ontogen_members
                    .iter()
                    .skip(ontogen_offset as usize)
                    .take(ontogen_limit as usize)
                    .map(|ontogen_member| OntogenResourceIdentifier::new("tags", ontogen_member.id.as_str()))
                    .collect(),
            );
            let ontogen_base =
                format!("{ontogen_collection}/{}", ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id));
            let ontogen_self = format!("{ontogen_base}/relationships/labels");
            let ontogen_links = ::ontogen_jsonapi::links::pagination_links(
                &ontogen_self,
                &OntogenCanonicalQuery::new(),
                ontogen_offset,
                ontogen_limit,
                ontogen_total,
            )
            .with_related(format!("{ontogen_base}/labels"));
            Ok(::ontogen_jsonapi::response::ok(
                &OntogenDocument::new(ontogen_data, ontogen_links).with_meta(OntogenPageMeta {
                    total: ontogen_total,
                    limit: ontogen_limit,
                    offset: ontogen_offset,
                }),
            ))
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("tasks", &rel)),
    }
}

