async fn ontogen_task_related_get(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    OntogenPath((id, rel)): OntogenPath<(OntogenLookupKey, OntogenLookupKey)>,
    OntogenRawQuery(ontogen_raw_query): OntogenRawQuery,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_collection = "/api/tasks";
    match rel.as_str() {
        Some("parent") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_task_fetch(&ontogen_state, ontogen_entity.parent_id.as_slice()).await?;
            let ontogen_data =
                ontogen_related.first().map(|ontogen_member| ontogen_task_as_resource(ontogen_member, "/api/tasks"));
            let ontogen_self = format!(
                "{ontogen_collection}/{}/parent",
                ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id)
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, OntogenLinks::new(ontogen_self))))
        }
        Some("subtasks") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_task_fetch(&ontogen_state, &ontogen_entity.subtasks).await?;
            let ontogen_data: Vec<_> = ontogen_related
                .iter()
                .map(|ontogen_member| ontogen_task_as_resource(ontogen_member, "/api/tasks"))
                .collect();
            let ontogen_self = format!(
                "{ontogen_collection}/{}/subtasks",
                ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id)
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, OntogenLinks::new(ontogen_self))))
        }
        Some("tags") => {
            OntogenQueryParams::parse(ontogen_raw_query.as_deref(), &OntogenQuerySpec::NONE)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_tag_fetch(&ontogen_state, &ontogen_entity.tags).await?;
            let ontogen_data: Vec<_> = ontogen_related
                .iter()
                .map(|ontogen_member| ontogen_tag_as_resource(ontogen_member, "/api/tags"))
                .collect();
            let ontogen_self = format!(
                "{ontogen_collection}/{}/tags",
                ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id)
            );
            Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::new(ontogen_data, OntogenLinks::new(ontogen_self))))
        }
        Some("labels") => {
            let ontogen_query = OntogenQueryParams::parse(
                ontogen_raw_query.as_deref(),
                &OntogenQuerySpec { page: true, ..OntogenQuerySpec::NONE },
            )?;
            let (ontogen_offset, ontogen_limit) = ontogen_page(&ontogen_query, 2, 3)?;
            let ontogen_entity = ontogen_task_read(&ontogen_state, &id).await?;
            let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
            let ontogen_members =
                task::list_labels(&ontogen_store, &ontogen_entity.id).await.map_err(ontogen_app_error)?;
            let ontogen_total = ontogen_members.len() as u64;
            let ontogen_data: Vec<_> = ontogen_members
                .iter()
                .skip(ontogen_offset as usize)
                .take(ontogen_limit as usize)
                .map(|ontogen_member| ontogen_tag_as_resource(ontogen_member, "/api/tags"))
                .collect();
            let ontogen_self = format!(
                "{ontogen_collection}/{}/labels",
                ::ontogen_jsonapi::links::encode_path_segment(&ontogen_entity.id)
            );
            let ontogen_links = ::ontogen_jsonapi::links::pagination_links(
                &ontogen_self,
                &OntogenCanonicalQuery::new(),
                ontogen_offset,
                ontogen_limit,
                ontogen_total,
            );
            Ok(::ontogen_jsonapi::response::ok(
                &OntogenDocument::new(ontogen_data, ontogen_links).with_meta(OntogenPageMeta {
                    total: ontogen_total,
                    limit: ontogen_limit,
                    offset: ontogen_offset,
                }),
            ))
        }
        _ => Err(::ontogen_jsonapi::error::no_such_relationship("tasks", &rel)),
    }
}

// ── Outline Handlers ──

struct OntogenOutlineListFilterParams;

impl OntogenRouteQuery for OntogenOutlineListFilterParams {
    const SPEC: OntogenQuerySpec =
        OntogenQuerySpec { filter: &["title_contains"], op_args: &["limit", "offset"], ..OntogenQuerySpec::NONE };
}

async fn outline_list(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    ontogen_query: OntogenQuery<OntogenOutlineListFilterParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let ontogen_filter_title_contains = ontogen_query.filter_member::<String>("title_contains")?;
    let ontogen_limit = ontogen_query.page_op_arg("limit")?.unwrap_or(2).min(3);
    let ontogen_offset = ontogen_query.page_op_arg("offset")?.unwrap_or(0);
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let ontogen_items = outline::list(
        &ontogen_store,
        ontogen_filter_title_contains.clone(),
        Some(u64::from(ontogen_limit)),
        Some(u64::from(ontogen_offset)),
    )
    .await
    .map_err(ontogen_app_error)?;
    let ontogen_total =
        outline::count(&ontogen_store, ontogen_filter_title_contains).await.map_err(ontogen_app_error)?;
    let ontogen_result = OntogenPaginatedResult {
        items: ontogen_items,
        total: ontogen_total,
        limit: ontogen_limit,
        offset: ontogen_offset,
    };
    Ok(::ontogen_jsonapi::response::ok(&OntogenDocument::meta_only(OntogenResultMeta { result: ontogen_result })))
}

